SELECT data_rows.user_id, data_rows.provider, data_rows.enc_token, data_rows.created_at, data_rows.updated_at, data_rows.version, data_rows.lease_owner, data_rows.lease_until, data_rows.refresh_status FROM  (SELECT `user_id`, `provider`, `enc_token`, `created_at`, `updated_at`, `version`, `lease_owner`, `lease_until`, `refresh_status` FROM user_oauth_token)  data_rows